const k=api.label;
function Text({name}:{name:ConfigurationLabel}){return <ContentText contentKey={k(name)}/>;}
const Labels=createContext<api.Presentation|undefined>(undefined);
function Option({value,name}:{value:string;name:ConfigurationLabel}){const item=useContext(Labels)!.content[k(name)]!;return <option value={value} data-content-key={item.key} data-content-version={item.versionRef} data-content-publication={item.publicationRef}>{item.text}</option>;}
const has=(cap:Capabilities|undefined,action:Action)=>cap?.availableActions.includes(action)===true;
