 const [workspaceCap,setWorkspaceCap]=useState<Capabilities>(),[proposalCap,setProposalCap]=useState<Capabilities>();
 const [candidates,setCandidates]=useState<Proposal[]>([]),[nextProposal,setNextProposal]=useState<number|null>(null),[proposalOffset,setProposalOffset]=useState(0);
