 const [publications,setPublications]=useState<Publication[]>([]),[head,setHead]=useState<Publication>(),[historyCaps,setHistoryCaps]=useState<Record<string,Capabilities>>({}),[historyOffset,setHistoryOffset]=useState(0),[nextHistory,setNextHistory]=useState<number|null>(null);
