 const [notice,setNotice]=useState<ConfigurationLabel>(),[busy,setBusy]=useState(false),[qualifiedRequest,setQualifiedRequest]=useState(''),[unknown,setUnknown]=useState(false),[reload,setReload]=useState(0),[confirmation,setConfirmation]=useState<Confirmation>();
 const pending=useRef(false),intent=useRef<Intent|undefined>(undefined),reads=useRef<AbortController|undefined>(undefined),writes=useRef<AbortController|undefined>(undefined),heading=useRef<HTMLHeadingElement>(null);
 const workspace=boot?.workspaces.find(value=>value.scope.family===family&&api.scopeKey(value.scope)===selectedScope),presentation=boot?.presentation;
 const context=useRef('');context.current=JSON.stringify([family,selectedScope,selectedId]);
 const requestKey=JSON.stringify([location.revision,family,selectedScope,selectedId,submittedSearch,proposalOffset,historyOffset,reload,workspace?.governanceVersion,...(family==='RecoveryPasswordContent'?[workspace?.recoveryPasswordContentOwnerFacts]:[])]);
 const currentRequest=useRef(requestKey);currentRequest.current=requestKey;
