 function clearScope(){clearCandidate();setWorkspaceCap(undefined);setCandidates([]);setPublications([]);setHistoryCaps({});setHead(undefined);setProposalOffset(0);setHistoryOffset(0);setNextHistory(null);setNextProposal(null);setSearch('');setSubmittedSearch('');}
 function error(value:unknown){if(value instanceof api.ConfigurationHttpError&&[401,403].includes(value.status)){setBlocked(true);clearScope();setNotice('noAccess');}else if(value instanceof api.ConfigurationHttpError&&value.status===409){setProposalCap(undefined);setNotice('conflict');}else if(value instanceof api.ConfigurationHttpError&&value.status===400)setNotice('validationSummary');else setNotice('unavailable');}
